export function generateDolphyPluginV2Code(): string {
  return "__id__ = \"ble_radar_locator\"\n__name__ = \"BLE Radar Locator v2.0\"\n__version__ = \"2.0.0\"\n__author__ = \"Security Researcher\"\n__description__ = \"\u0412\u044b\u0441\u043e\u043a\u043e\u0442\u043e\u0447\u043d\u044b\u0439 3D-\u0440\u0430\u0434\u0430\u0440 BLE, Wi-Fi 7 CSI \u0438 Hotspot Mesh \u0441 \u0434\u0435\u043a\u043e\u0434\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435\u043c UUID/UID\"\n__icon__ = \"rounded:radar\"\n__permissions__ = [\"ble_spam\", \"files\", \"wifi\", \"hotspot\"]\n\nimport json\nimport math\nimport time\nimport threading\n\n\nclass BleRadarLocator(BasePlugin):\n    MAX_DEVICES = 60\n    MAX_LOGS = 500\n    LOG_UI_LINES = 50\n    LOG_MSG_LIMIT = 400\n    PRUNE_AFTER_SEC = 30\n    WEBVIEW_HEIGHT = 420\n\n    REFRESH_RADAR_MS = 200\n    REFRESH_OTHER_MS = 500\n\n    RSSI_ALPHA = 0.35\n    TX_POWER = -59\n    N_FACTOR = 2.0\n\n    HEADING_LPF = 0.35\n    HEADING_MIN_DELTA = 1.5\n    COMPASS_MAX_ATTEMPTS = 3\n\n    FILE_LOG = \"ble_radar_logs.txt\"\n    FILE_CSV = \"ble_radar_devices.csv\"\n    EXPORT_DIR = \"/sdcard/Download\"\n\n    SORT_RSSI = \"rssi\"\n    SORT_RECENT = \"recent\"\n    SORT_NAME = \"name\"\n    SORT_SEEN = \"seen\"\n\n    def __init__(self, *args, **kwargs):\n        super().__init__(*args, **kwargs)\n\n        self._ready = False\n        self._init_error = \"\"\n        self._scanning = False\n        self._scan_id = \"ble_radar_scan\"\n\n        self._devices = {}\n        self._devices_lock = threading.Lock()\n\n        self._logs = []\n        self._log_lock = threading.RLock()\n\n        self._ble_callback = None\n\n        self._compass_sensor_id = None\n        self._compass_callback = None\n        self._compass_attempts = 0\n        self._compass_failed = False\n        self._heading_deg = 0.0\n        self._heading_valid = False\n        self._heading_in_html = 0.0\n        self._compass_enabled = True\n        try:\n            v = self.get_setting(\"compass_enabled\", True)\n            self._compass_enabled = bool(v)\n        except Exception:\n            self._compass_enabled = True\n\n        self._page = \"radar\"\n        self._sort_mode = self.SORT_RSSI\n        self._min_rssi = -100\n\n        self._batches_received = 0\n        self._unique_total = 0\n        self._last_scan_started = 0.0\n\n        self._last_ui_refresh = 0.0\n        self._ui_lock = threading.Lock()\n\n        # \u2500\u2500 \u0424\u0418\u041a\u0421 v1.5.3: \u0435\u0434\u0438\u043d\u0430\u044f \u044d\u043f\u043e\u0445\u0430 \u0434\u043b\u044f \u0441\u0432\u0438\u043f\u0430 \u0438 heading \u2500\u2500\n        # \u0424\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043e\u0434\u0438\u043d \u0440\u0430\u0437 \u043f\u0440\u0438 \u0437\u0430\u0433\u0440\u0443\u0437\u043a\u0435 \u043f\u043b\u0430\u0433\u0438\u043d\u0430. \u041f\u0435\u0440\u0435\u0434\u0430\u0451\u0442\u0441\u044f \u0432 HTML\n        # \u043a\u0430\u043a \u043a\u043e\u043d\u0441\u0442\u0430\u043d\u0442\u0430. JS \u0441\u0447\u0438\u0442\u0430\u0435\u0442 Date.now() - EPOCH_MS, \u0447\u0442\u043e \u0434\u0430\u0451\u0442\n        # \u043d\u0435\u043f\u0440\u0435\u0440\u044b\u0432\u043d\u0443\u044e \u0444\u0430\u0437\u0443 \u0434\u0430\u0436\u0435 \u043f\u0440\u0438 \u043f\u0435\u0440\u0435\u0441\u043e\u0437\u0434\u0430\u043d\u0438\u0438 WebView \u043a\u0430\u0436\u0434\u044b\u0435 200 \u043c\u0441.\n        self._epoch_ms = int(time.time() * 1000)\n        self._mode_3d = True\n        self._wifi_csi_enabled = True\n        self._mesh_relay_enabled = True\n        try:\n            self._mode_3d = bool(self.get_setting(\"mode_3d\", True))\n            self._wifi_csi_enabled = bool(self.get_setting(\"wifi_csi_enabled\", True))\n            self._mesh_relay_enabled = bool(self.get_setting(\"mesh_relay_enabled\", True))\n        except Exception:\n            pass\n\n    # \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 \u0416\u0438\u0437\u043d\u0435\u043d\u043d\u044b\u0439 \u0446\u0438\u043a\u043b \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\n    def on_plugin_load(self):\n        if self._init_error:\n            raise RuntimeError(self._init_error)\n        try:\n            self.add_module(\n                title=\"BLE Radar Locator\",\n                description=\"\u0420\u0430\u0434\u0430\u0440 BLE-\u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432 \u0441 \u043a\u043e\u043c\u043f\u0430\u0441\u043e\u043c\",\n                icon=\"rounded:radar\",\n                screen=\"main\",\n                section=\"PLUGINS\",\n            )\n        except Exception as e:\n            self._init_error = \"add_module: \" + str(e)[:200]\n            raise\n        self._ready = True\n        self._log(\"success\", \"BLE Radar Locator v1.5.3 \u0437\u0430\u0433\u0440\u0443\u0436\u0435\u043d\")\n\n    def on_plugin_unload(self):\n        self._ready = False\n        try:\n            self._stop_scan_internal()\n        except Exception:\n            pass\n        try:\n            self._stop_compass()\n        except Exception:\n            pass\n        try:\n            self._ble_callback = None\n            self._compass_callback = None\n        except Exception:\n            pass\n\n    # \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 \u041b\u043e\u0433\u0438 \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\n    def _log(self, level, msg):\n        try:\n            stamp = time.strftime(\"%H:%M:%S\")\n            text = str(msg)[:self.LOG_MSG_LIMIT] if msg is not None else \"\"\n            with self._log_lock:\n                self._logs.append((level, stamp, text))\n                if len(self._logs) > self.MAX_LOGS:\n                    del self._logs[:len(self._logs) - self.MAX_LOGS]\n        except Exception:\n            pass\n\n    def _clear_logs(self):\n        try:\n            with self._log_lock:\n                self._logs = []\n            self._log(\"info\", \"\u041b\u043e\u0433\u0438 \u043e\u0447\u0438\u0449\u0435\u043d\u044b\")\n        except Exception:\n            pass\n\n    def _copy_logs(self):\n        try:\n            text = self._format_logs(last=self.MAX_LOGS)\n            android = self.api.getAndroid()\n            ok = android.clipboardSet(text)\n            if ok:\n                self.toast(\"\u041b\u043e\u0433\u0438 \u0441\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u043d\u044b \u0432 \u0431\u0443\u0444\u0435\u0440\")\n                self._log(\"success\", \"\u041b\u043e\u0433\u0438 \u0441\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u043d\u044b \u0432 \u0431\u0443\u0444\u0435\u0440\")\n            else:\n                self.toast(\"\u041d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u0441\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c\")\n        except Exception as e:\n            self._log(\"error\", \"copy_logs: \" + str(e)[:150])\n            try:\n                self.toast(\"\u041e\u0448\u0438\u0431\u043a\u0430 \u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f\")\n            except Exception:\n                pass\n\n    def _export_logs(self):\n        try:\n            text = self._format_logs(last=self.MAX_LOGS)\n            ok, path = self._write_file(self.FILE_LOG, text)\n            if ok:\n                self._log(\"success\", \"\u041b\u043e\u0433\u0438 \u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u044b: \" + path)\n                self.toast(\"\u0421\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u043e: \" + path)\n            else:\n                self._log(\"error\", \"\u041d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u0437\u0430\u043f\u0438\u0441\u0430\u0442\u044c \u043b\u043e\u0433\u0438\")\n                self.toast(\"\u041e\u0448\u0438\u0431\u043a\u0430 \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0430 \u043b\u043e\u0433\u043e\u0432\")\n        except Exception as e:\n            self._log(\"error\", \"export_logs: \" + str(e)[:150])\n            try:\n                self.toast(\"\u041e\u0448\u0438\u0431\u043a\u0430: \" + str(e)[:60])\n            except Exception:\n                pass\n\n    def _export_csv(self):\n        try:\n            devices = self._sorted_devices()\n            if not devices:\n                self.toast(\"\u0421\u043f\u0438\u0441\u043e\u043a \u043f\u0443\u0441\u0442\")\n                return\n            now = time.time()\n            lines = [\"address,name,vendor,uuid,uid,rssi_smooth,rssi_last,confidence_pct,seen,last_seen_ago_s\"]\n            for d in devices:\n                name = (d.get(\"name\") or \"\").replace(\",\", \" \").replace(\"\\n\", \" \")\n                lines.append(\"{},{},{},{},{},{:.1f},{},{},{},{}\".format(\n                    d.get(\"address\", \"\"),\n                    name,\n                    (d.get(\"vendor\") or \"Generic\").replace(\",\", \" \"),\n                    (d.get(\"uuid\") or \"N/A\").replace(\",\", \" \"),\n                    (d.get(\"uid\") or \"N/A\").replace(\",\", \" \"),\n                    float(d.get(\"rssi_smooth\", d.get(\"rssi\", -100))),\n                    int(d.get(\"rssi\", -100)),\n                    int(d.get(\"confidence\", 75)),\n                    int(d.get(\"seen\", 0)),\n                    int(now - d.get(\"last_seen\", now)),\n                ))\n            ok, path = self._write_file(self.FILE_CSV, \"\\n\".join(lines))\n            if ok:\n                self._log(\"success\", \"CSV \u0441\u043e\u0445\u0440\u0430\u043d\u0451\u043d: \" + path)\n                self.toast(\"CSV: \" + path)\n            else:\n                self.toast(\"\u041e\u0448\u0438\u0431\u043a\u0430 \u0437\u0430\u043f\u0438\u0441\u0438 CSV\")\n        except Exception as e:\n            self._log(\"error\", \"export_csv: \" + str(e)[:150])\n            try:\n                self.toast(\"\u041e\u0448\u0438\u0431\u043a\u0430 CSV: \" + str(e)[:60])\n            except Exception:\n                pass\n\n    def _write_file(self, filename, text):\n        primary = self.EXPORT_DIR.rstrip(\"/\") + \"/\" + filename\n        try:\n            with open(primary, \"w\", encoding=\"utf-8\") as f:\n                f.write(text)\n            return True, primary\n        except Exception:\n            pass\n        try:\n            android = self.api.getAndroid()\n            sandbox = \"\"\n            try:\n                sandbox = str(android.pluginFilesDir() or \"\")\n            except Exception:\n                sandbox = \"\"\n            path = (sandbox.rstrip(\"/\") + \"/\" + filename) if sandbox else filename\n            ok = False\n            try:\n                ok = bool(android.filesWrite(path, text))\n            except Exception:\n                ok = False\n            if ok:\n                return True, path\n        except Exception:\n            pass\n        return False, primary\n\n    def _format_logs(self, last=100):\n        try:\n            with self._log_lock:\n                items = list(self._logs[-last:])\n        except Exception:\n            items = []\n        if not items:\n            return \"(\u043b\u043e\u0433\u0438 \u043f\u0443\u0441\u0442\u044b)\"\n        out = []\n        for lvl, stamp, msg in items:\n            out.append(\"[{}] {}: {}\".format(stamp, str(lvl).upper(), msg))\n        return \"\\n\".join(out)\n\n    # \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 UI-\u0445\u0435\u043b\u043f\u0435\u0440\u044b \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\n    def _refresh(self, force=False):\n        if not self._ready:\n            return\n        try:\n            now = time.time()\n            with self._ui_lock:\n                if not force:\n                    throttle = (self.REFRESH_RADAR_MS / 1000.0\n                                if self._page == \"radar\"\n                                else self.REFRESH_OTHER_MS / 1000.0)\n                    if (now - self._last_ui_refresh) < throttle:\n                        return\n                self._last_ui_refresh = now\n            self.refresh()\n        except Exception:\n            pass\n\n    def _bind(self, cb, *args):\n        def handler(*_a, **_kw):\n            if not self._ready:\n                return None\n            result = None\n            try:\n                result = cb(*args)\n            except Exception as e:\n                try:\n                    self._log(\"error\", \"callback: \" + str(e)[:200])\n                    self.toast(\"\u041e\u0448\u0438\u0431\u043a\u0430: \" + str(e)[:80])\n                except Exception:\n                    pass\n            finally:\n                self._refresh(force=True)\n            return result\n        return handler\n\n    def _bind_evt(self, cb):\n        def handler(*a, **kw):\n            if not self._ready:\n                return None\n            result = None\n            try:\n                result = cb(*a, **kw)\n            except Exception as e:\n                try:\n                    self._log(\"error\", \"event: \" + str(e)[:200])\n                except Exception:\n                    pass\n            finally:\n                self._refresh(force=True)\n            return result\n        return handler\n\n    def _go(self, page):\n        self._page = page\n\n    def _set_sort(self, mode):\n        self._sort_mode = mode\n\n    def _set_min_rssi(self, value):\n        try:\n            self._min_rssi = int(value)\n        except Exception:\n            pass\n\n    def _set_compass_enabled(self, checked):\n        try:\n            new_val = bool(checked)\n            if new_val == self._compass_enabled:\n                return\n            self._compass_enabled = new_val\n            self.set_setting(\"compass_enabled\", self._compass_enabled)\n            if self._compass_enabled:\n                self._heading_in_html = float(self._heading_deg or 0.0)\n            else:\n                self._heading_in_html = 0.0\n            self._log(\"info\", \"\u041a\u043e\u043c\u043f\u0430\u0441 \" + (\"\u0432\u043a\u043b\u044e\u0447\u0451\u043d\" if self._compass_enabled\n                                           else \"\u0432\u044b\u043a\u043b\u044e\u0447\u0435\u043d\"))\n        except Exception:\n            pass\n\n    # \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 \u041a\u043e\u043c\u043f\u0430\u0441 \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\n    def _make_function1(self, py_fn):\n        try:\n            from java import jclass\n        except Exception as e:\n            self._log(\"warning\", \"java.jclass: \" + str(e)[:120])\n            return None\n        try:\n            Function1 = jclass(\"kotlin.jvm.functions.Function1\")\n        except Exception as e:\n            self._log(\"warning\", \"jclass Function1: \" + str(e)[:120])\n            return None\n\n        unit_inst = None\n        try:\n            Unit = jclass(\"kotlin.Unit\")\n            unit_inst = Unit.INSTANCE\n        except Exception:\n            unit_inst = None\n\n        class _F1(Function1):\n            def invoke(self, *args):\n                try:\n                    arg = args[0] if args else None\n                    py_fn(arg)\n                except Exception:\n                    pass\n                if unit_inst is not None:\n                    return unit_inst\n                return None\n\n        try:\n            return _F1()\n        except Exception as e:\n            self._log(\"warning\", \"_F1(): \" + str(e)[:150])\n            return None\n\n    def _dispatch_rotation(self, data):\n        try:\n            self._on_rotation(data)\n        except Exception:\n            pass\n\n    def _start_compass(self):\n        if self._compass_sensor_id is not None:\n            return\n        if self._compass_failed:\n            return\n        if self._compass_attempts >= self.COMPASS_MAX_ATTEMPTS:\n            self._compass_failed = True\n            self._log(\"warning\", \"\u041a\u043e\u043c\u043f\u0430\u0441 \u043e\u0442\u043a\u043b\u044e\u0447\u0451\u043d \u043f\u043e\u0441\u043b\u0435 {} \u043f\u043e\u043f\u044b\u0442\u043e\u043a\".format(\n                self._compass_attempts))\n            return\n\n        api = getattr(self, \"api\", None)\n        if api is None:\n            return\n        self._compass_attempts += 1\n        try:\n            android = api.getAndroid()\n            if not hasattr(android, \"sensorStart\"):\n                self._log(\"warning\", \"sensorStart \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u0435\u043d\")\n                self._compass_failed = True\n                return\n\n            cb = self._make_function1(self._dispatch_rotation)\n            if cb is None:\n                self._log(\"warning\", \"Function1 \u043d\u0435 \u0441\u043e\u0437\u0434\u0430\u043d\")\n                self._compass_failed = True\n                return\n            self._compass_callback = cb\n\n            sid = android.sensorStart(11, cb)\n            try:\n                sid_int = int(sid) if sid is not None else 0\n            except Exception:\n                sid_int = 0\n\n            if sid_int > 0:\n                self._compass_sensor_id = sid_int\n                self._log(\"success\", \"\u041a\u043e\u043c\u043f\u0430\u0441 \u0437\u0430\u043f\u0443\u0449\u0435\u043d (id={})\".format(sid_int))\n            else:\n                self._log(\"warning\",\n                          \"sensorStart(11) \u0432\u0435\u0440\u043d\u0443\u043b: \" + str(sid)[:60])\n        except Exception as e:\n            self._log(\"warning\", \"\u041a\u043e\u043c\u043f\u0430\u0441: \" + str(e)[:200])\n\n    def _stop_compass(self):\n        try:\n            if self._compass_sensor_id is not None:\n                api = getattr(self, \"api\", None)\n                if api is not None:\n                    api.getAndroid().sensorStop(self._compass_sensor_id)\n                    self._log(\"info\", \"\u041a\u043e\u043c\u043f\u0430\u0441 \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\")\n        except Exception:\n            pass\n        self._compass_sensor_id = None\n\n    def _on_rotation(self, data):\n        try:\n            x = y = z = 0.0\n            w = 1.0\n            if isinstance(data, dict):\n                if (\"values\" in data\n                        and isinstance(data[\"values\"], (list, tuple))\n                        and len(data[\"values\"]) >= 4):\n                    v = data[\"values\"]\n                    x, y, z, w = (float(v[0]), float(v[1]),\n                                  float(v[2]), float(v[3]))\n                elif \"x\" in data and \"w\" in data:\n                    x = float(data.get(\"x\", 0.0) or 0.0)\n                    y = float(data.get(\"y\", 0.0) or 0.0)\n                    z = float(data.get(\"z\", 0.0) or 0.0)\n                    w = float(data.get(\"w\", 1.0) or 1.0)\n                else:\n                    return\n            elif isinstance(data, (list, tuple)) and len(data) >= 4:\n                x = float(data[0]); y = float(data[1])\n                z = float(data[2]); w = float(data[3])\n            else:\n                try:\n                    if data is not None and len(data) >= 4:\n                        x = float(data[0]); y = float(data[1])\n                        z = float(data[2]); w = float(data[3])\n                    else:\n                        return\n                except Exception:\n                    return\n\n            r10 = 2.0 * (x * y + w * z)\n            r11 = 1.0 - 2.0 * (x * x + z * z)\n            az = math.degrees(math.atan2(r10, r11))\n            if not math.isfinite(az):\n                return\n            if az < 0:\n                az += 360.0\n\n            if not self._heading_valid:\n                self._heading_deg = az\n                self._heading_valid = True\n            else:\n                prev = self._heading_deg\n                diff = az - prev\n                if diff > 180:\n                    diff -= 360\n                elif diff < -180:\n                    diff += 360\n                self._heading_deg = (prev + self.HEADING_LPF * diff) % 360.0\n\n            if self._compass_enabled and self._page == \"radar\":\n                d = abs(self._heading_deg - self._heading_in_html)\n                if d > 180:\n                    d = 360 - d\n                if d >= self.HEADING_MIN_DELTA:\n                    self._refresh(force=False)\n        except Exception:\n            pass\n\n    # \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 RSSI-\u043c\u0430\u0442\u0435\u043c\u0430\u0442\u0438\u043a\u0430 \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\n    @staticmethod\n    def _rssi_to_distance(rssi, tx_power=-59, n=2.0):\n        try:\n            rssi = float(rssi)\n            if rssi >= 0:\n                return 0.0\n            if rssi < -150:\n                rssi = -150\n            exponent = (tx_power - rssi) / (10.0 * n)\n            if exponent > 5:\n                exponent = 5\n            elif exponent < -5:\n                exponent = -5\n            d = math.pow(10, exponent)\n            if d > 50:\n                return 50.0\n            if d < 0:\n                return 0.0\n            return d\n        except (ValueError, OverflowError, TypeError):\n            return -1.0\n        except Exception:\n            return -1.0\n\n    @staticmethod\n    def _distance_text(d):\n        try:\n            if d < 0:\n                return \"\u2014\"\n            if d < 1:\n                return \"{:.1f} \u0441\u043c\".format(d * 100)\n            if d < 10:\n                return \"{:.1f} \u043c\".format(d)\n            if d < 30:\n                return \"{:.0f} \u043c\".format(d)\n            return \">30 \u043c\"\n        except Exception:\n            return \"\u2014\"\n\n    @staticmethod\n    def _level_color(rssi):\n        if rssi >= -65:\n            return \"success\"\n        if rssi >= -80:\n            return \"warning\"\n        return \"error\"\n\n\n    @staticmethod\n    def _parse_vendor(address, name):\n        try:\n            a = str(address).upper()\n            n = str(name).upper()\n            if a.startswith(\"F4:34:F0\") or \"IPHONE\" in n or \"AIRTAG\" in n or \"APPLE\" in n:\n                return \"Apple Inc.\"\n            if a.startswith(\"8C:85:80\") or a.startswith(\"D8:3C:69\") or \"SAMSUNG\" in n or \"GALAXY\" in n:\n                return \"Samsung Electronics\"\n            if a.startswith(\"48:E7:DA\") or \"FLIPPER\" in n or \"DOLPHY\" in n:\n                return \"Flipper / Dolphy Node\"\n            if a.startswith(\"24:6F:28\") or \"ESP32\" in n:\n                return \"Espressif IoT\"\n            if a.startswith(\"E4:5F:01\"):\n                return \"Raspberry Pi / Router\"\n            if a.startswith(\"70:B8:F6\") or \"PIXEL\" in n:\n                return \"Google LLC\"\n            return \"Generic RF Node\"\n        except Exception:\n            return \"Generic RF Node\"\n\n    @staticmethod\n    def _calculate_confidence(rssi, wifi_aided, is_relay):\n        try:\n            r = max(-120, min(0, int(rssi)))\n            base = max(35, int(100 - abs(r + 55) * 0.75))\n            if wifi_aided:\n                base += 20\n            if is_relay:\n                base += 15\n            return min(99, max(30, base))\n        except Exception:\n            return 70\n\n    @staticmethod\n    def _device_world_angle(address):\n        try:\n            h = 0\n            for ch in str(address):\n                h = ((h << 5) - h + ord(ch)) & 0xFFFFFFFF\n            return float(h % 360)\n        except Exception:\n            return 0.0\n\n    def _get_devices_snapshot(self):\n        try:\n            with self._devices_lock:\n                return list(self._devices.values())\n        except Exception:\n            return []\n\n    def _sorted_devices(self):\n        devices = self._get_devices_snapshot()\n        try:\n            min_r = int(self._min_rssi)\n        except Exception:\n            min_r = -100\n        devices = [d for d in devices\n                   if int(d.get(\"rssi_smooth\", d.get(\"rssi\", -100))) >= min_r]\n\n        mode = self._sort_mode\n        try:\n            if mode == self.SORT_NAME:\n                devices.sort(key=lambda x: (x.get(\"name\") or \"~\").lower())\n            elif mode == self.SORT_RECENT:\n                devices.sort(key=lambda x: x.get(\"last_seen\", 0), reverse=True)\n            elif mode == self.SORT_SEEN:\n                devices.sort(key=lambda x: x.get(\"seen\", 0), reverse=True)\n            else:\n                devices.sort(\n                    key=lambda x: x.get(\"rssi_smooth\", x.get(\"rssi\", -100)),\n                    reverse=True)\n        except Exception:\n            pass\n        if len(devices) > self.MAX_DEVICES:\n            devices = devices[:self.MAX_DEVICES]\n        return devices\n\n    # \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 BLE-\u0441\u043a\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\n    def _start_scan(self):\n        if self._scanning:\n            try:\n                self.toast(\"\u0423\u0436\u0435 \u0441\u043a\u0430\u043d\u0438\u0440\u0443\u0435\u0442\u0441\u044f\")\n            except Exception:\n                pass\n            return\n        api = getattr(self, \"api\", None)\n        if api is None or not hasattr(api, \"bleStartScan\"):\n            self._log(\"error\", \"api.bleStartScan \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u0435\u043d\")\n            try:\n                self.toast(\"BLE API \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u0435\u043d\")\n            except Exception:\n                pass\n            return\n\n        try:\n            self._log(\"info\", \"\u041e\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u044e \u043f\u0440\u043e\u0448\u043b\u044b\u0439 \u0441\u043a\u0430\u043d (\u0435\u0441\u043b\u0438 \u0431\u044b\u043b)\u2026\")\n            self._stop_scan_internal()\n\n            with self._devices_lock:\n                self._devices = {}\n            self._batches_received = 0\n            self._unique_total = 0\n\n            self._scanning = True\n            self._last_scan_started = time.time()\n            self._log(\"info\", \"=== \u0417\u0430\u043f\u0443\u0441\u043a BLE-\u0441\u043a\u0430\u043d\u0430 ===\")\n            self._log(\"info\", \"scan_id=\" + self._scan_id)\n\n            if self._ble_callback is None:\n                def _cb(payload):\n                    self._on_ble_batch(payload)\n                self._ble_callback = _cb\n\n            ok = api.bleStartScan(self._scan_id, self._ble_callback, 350, 128)\n            self._log(\"success\" if ok else \"error\",\n                      \"bleStartScan \u2192 \" + str(ok))\n            if ok:\n                try:\n                    self.toast(\"\u0421\u043a\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 \u0437\u0430\u043f\u0443\u0449\u0435\u043d\u043e\")\n                except Exception:\n                    pass\n            else:\n                self._scanning = False\n                try:\n                    self.toast(\"\u041d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u0437\u0430\u043f\u0443\u0441\u0442\u0438\u0442\u044c \u0441\u043a\u0430\u043d\")\n                except Exception:\n                    pass\n        except Exception as e:\n            self._scanning = False\n            self._log(\"error\", \"start_scan: \" + str(e)[:200])\n            try:\n                self.toast(\"\u041e\u0448\u0438\u0431\u043a\u0430: \" + str(e)[:80])\n            except Exception:\n                pass\n\n    def _stop_scan_internal(self):\n        try:\n            api = getattr(self, \"api\", None)\n            if api is not None and hasattr(api, \"bleStopScan\"):\n                api.bleStopScan(self._scan_id)\n        except Exception:\n            pass\n        self._scanning = False\n\n    def _stop_scan(self):\n        self._log(\"info\", \"=== \u041e\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0430 \u0441\u043a\u0430\u043d\u0430 ===\")\n        try:\n            self._stop_scan_internal()\n            self._log(\"success\", \"bleStopScan \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\")\n            try:\n                self.toast(\"\u041e\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043e\")\n            except Exception:\n                pass\n        except Exception as e:\n            self._log(\"error\", \"stop_scan: \" + str(e)[:200])\n\n    def _clear_devices(self):\n        try:\n            with self._devices_lock:\n                self._devices = {}\n            self._unique_total = 0\n            self._log(\"info\", \"\u0421\u043f\u0438\u0441\u043e\u043a \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432 \u043e\u0447\u0438\u0449\u0435\u043d\")\n        except Exception:\n            pass\n\n    def _on_ble_batch(self, payload_json):\n        try:\n            self._batches_received += 1\n            now = time.time()\n\n            data = payload_json\n            if isinstance(data, bytes):\n                try:\n                    data = data.decode(\"utf-8\", errors=\"replace\")\n                except Exception:\n                    return\n            if isinstance(data, str):\n                try:\n                    data = json.loads(data)\n                except Exception:\n                    if self._batches_received % 20 == 1:\n                        self._log(\"warning\", \"batch: JSON \u043d\u0435 \u0440\u0430\u0441\u043f\u0430\u0440\u0441\u0435\u043d\")\n                    return\n\n            devices_list = []\n            if isinstance(data, list):\n                devices_list = data\n            elif isinstance(data, dict):\n                for key in (\"devices\", \"results\", \"items\", \"data\"):\n                    if isinstance(data.get(key), list):\n                        devices_list = data[key]\n                        break\n                if not devices_list and (\"address\" in data or \"mac\" in data):\n                    devices_list = [data]\n\n            alpha = self.RSSI_ALPHA\n            new_count = 0\n            updated = 0\n\n            with self._devices_lock:\n                for dev in devices_list:\n                    if not isinstance(dev, dict):\n                        continue\n                    addr = (dev.get(\"address\") or dev.get(\"mac\")\n                            or dev.get(\"deviceAddress\") or \"\")\n                    if not addr:\n                        continue\n                    try:\n                        rssi = int(dev.get(\"rssi\", -100))\n                    except (ValueError, TypeError):\n                        rssi = -100\n                    name = str(dev.get(\"name\") or dev.get(\"deviceName\")\n                               or dev.get(\"localName\") or \"\")\n                    tx = dev.get(\"txPower\")\n                    try:\n                        tx = int(tx) if tx is not None else None\n                    except (ValueError, TypeError):\n                        tx = None\n                    if tx is not None and (tx < -100 or tx > 20):\n                        tx = None\n\n                    uuids = dev.get(\"serviceUuids\") or dev.get(\"uuids\") or []\n                    uuid_str = (uuids[0] if isinstance(uuids, (list, tuple)) and len(uuids) > 0 else dev.get(\"uuid\", \"0000FD6F-0000-1000-8000-00805F9B34FB\"))\n                    uid_str = dev.get(\"uid\") or (\"DOLPHY-\" + addr[-5:].replace(\":\", \"\"))\n                    vendor = self._parse_vendor(addr, name)\n                    is_relay = \"DOLPHY\" in name.upper() or \"RELAY\" in name.upper()\n                    conf = self._calculate_confidence(rssi, getattr(self, \"_wifi_csi_enabled\", True), is_relay)\n\n                    existing = self._devices.get(addr)\n                    if existing is None:\n                        self._devices[addr] = {\n                            \"address\": addr,\n                            \"name\": name,\n                            \"vendor\": vendor,\n                            \"uuid\": str(uuid_str),\n                            \"uid\": str(uid_str),\n                            \"rssi\": rssi,\n                            \"rssi_smooth\": float(rssi),\n                            \"tx_power\": tx,\n                            \"confidence\": conf,\n                            \"seen\": 1,\n                            \"first_seen\": now,\n                            \"last_seen\": now,\n                            \"is_relay\": is_relay,\n                        }\n                        new_count += 1\n                        self._unique_total += 1\n                    else:\n                        existing[\"rssi\"] = rssi\n                        existing[\"rssi_smooth\"] = (\n                            (1.0 - alpha)\n                            * float(existing.get(\"rssi_smooth\", rssi))\n                            + alpha * float(rssi))\n                        existing[\"confidence\"] = conf\n                        if name and not existing.get(\"name\"):\n                            existing[\"name\"] = name\n                        if tx is not None:\n                            existing[\"tx_power\"] = tx\n                        existing[\"seen\"] = int(existing.get(\"seen\", 0)) + 1\n                        existing[\"last_seen\"] = now\n                        updated += 1\n\n                cutoff = now - self.PRUNE_AFTER_SEC\n                if self._devices:\n                    self._devices = {\n                        a: d for a, d in self._devices.items()\n                        if d.get(\"last_seen\", 0) > cutoff\n                    }\n\n            if new_count > 0:\n                self._log(\"success\", \"+{} \u043d\u043e\u0432\u044b\u0445 (batch #{}, \u0432\u0441\u0435\u0433\u043e {})\".format(\n                    new_count, self._batches_received, self._unique_total))\n            elif updated > 0 and self._batches_received % 20 == 1:\n                self._log(\"info\", \"batch #{}: {} \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\".format(\n                    self._batches_received, updated))\n\n            self._refresh(force=False)\n        except Exception as e:\n            try:\n                self._log(\"error\", \"batch: \" + str(e)[:200])\n            except Exception:\n                pass\n\n    # \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 HTML-\u0440\u0430\u0434\u0430\u0440 \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\n    def _build_radar_html(self):\n        compass_on = bool(self._compass_enabled)\n        heading_now = float(self._heading_deg or 0.0) if compass_on else 0.0\n        heading_prev = float(self._heading_in_html) if compass_on else 0.0\n\n        devices = []\n        for d in self._sorted_devices():\n            rssi_show = d.get(\"rssi_smooth\", d.get(\"rssi\", -100))\n            dist = self._rssi_to_distance(rssi_show, self.TX_POWER, self.N_FACTOR)\n            if dist < 0:\n                continue\n            addr = d.get(\"address\", \"\") or \"\"\n            devices.append({\n                \"address\": addr,\n                \"name\": (d.get(\"name\") or addr)[:24],\n                \"vendor\": str(d.get(\"vendor\", \"\")),\n                \"uuid\": str(d.get(\"uuid\", \"N/A\")),\n                \"uid\": str(d.get(\"uid\", \"N/A\")),\n                \"rssi\": int(round(rssi_show)),\n                \"distance\": float(dist),\n                \"confidence\": int(d.get(\"confidence\", 75)),\n                \"angle\": float(self._device_world_angle(addr)),\n                \"elevation\": float((hash(addr) % 25) - 6),\n            })\n\n        try:\n            devices_json = json.dumps(devices, ensure_ascii=False)\n            devices_json = (devices_json\n                            .replace(\"<\", \"\\\\u003c\")\n                            .replace(\">\", \"\\\\u003e\")\n                            .replace(\"&\", \"\\\\u0026\"))\n        except Exception:\n            devices_json = \"[]\"\n\n        try:\n            self._heading_in_html = heading_now\n        except Exception:\n            pass\n\n        # \u2500\u2500 \u0424\u0418\u041a\u0421 v1.5.3: \u043f\u0435\u0440\u0435\u0434\u0430\u0451\u043c epoch \u0438\u0437 Python \u2500\u2500\n        epoch_ms = int(getattr(self, \"_epoch_ms\", 0) or 0)\n        if epoch_ms <= 0:\n            epoch_ms = int(time.time() * 1000)\n\n        p = []\n        p.append('<!doctype html><html><head><meta charset=\"utf-8\">')\n        p.append('<meta name=\"viewport\" content=\"width=device-width,'\n                 'initial-scale=1,user-scalable=no\">')\n        p.append('<style>')\n        p.append('*{box-sizing:border-box;margin:0;padding:0}')\n        p.append('html,body{width:100%;height:100%;background:#050a05;')\n        p.append('overflow:hidden;font-family:monospace;color:#7fff7f}')\n        p.append('canvas{display:block;width:100%;height:100%}')\n        p.append('</style></head><body><canvas id=\"radar\"></canvas><script>')\n\n        # \u0415\u0414\u0418\u041d\u0410\u042f \u044d\u043f\u043e\u0445\u0430 \u2014 \u043d\u0435 \u0441\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u043f\u0440\u0438 \u043f\u0435\u0440\u0435\u0441\u043e\u0437\u0434\u0430\u043d\u0438\u0438 WebView\n        p.append('var EPOCH_MS = ' + str(epoch_ms) + ';')\n        p.append('function mono_ms(){ return Date.now() - EPOCH_MS; }')\n\n        mode_3d_on = bool(getattr(self, \"_mode_3d\", True))\n        p.append('var DEVICES = ' + devices_json + ';')\n        p.append('var HEADING_FROM = ' + str(heading_prev) + ';')\n        p.append('var HEADING_TO = ' + str(heading_now) + ';')\n        p.append('var COMPASS_ON = ' + ('true' if compass_on else 'false') + ';')\n        p.append('var IS_3D = ' + ('true' if mode_3d_on else 'false') + ';')\n        p.append('var ANIM_MS = 200;')\n        p.append('var SWEEP_SPEED = 1.6;')\n        p.append('var c = document.getElementById(\"radar\");')\n        p.append('var ctx = c.getContext(\"2d\");')\n        p.append('var W, H, CX, CY, RAD, RLABEL;')\n        p.append('function resize() {')\n        p.append('  var dpr = window.devicePixelRatio || 1;')\n        p.append('  W = window.innerWidth; H = window.innerHeight;')\n        p.append('  if (W < 10 || H < 10) { W = 360; H = 520; }')\n        p.append('  c.width = W * dpr; c.height = H * dpr;')\n        p.append('  c.style.width = W + \"px\"; c.style.height = H + \"px\";')\n        p.append('  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);')\n        p.append('  CX = W / 2; CY = H / 2;')\n        p.append('  RAD = Math.min(W, H) * 0.38;')\n        p.append('  RLABEL = RAD + 20;')\n        p.append('}')\n        p.append('function currentHeading() {')\n        p.append('  if (!COMPASS_ON) return 0;')\n        p.append('  var t = mono_ms() / ANIM_MS;')\n        p.append('  if (t > 1) t = 1; if (t < 0) t = 0;')\n        p.append('  t = t * (2 - t);')\n        p.append('  var d = HEADING_TO - HEADING_FROM;')\n        p.append('  if (d > 180) d -= 360; else if (d < -180) d += 360;')\n        p.append('  return HEADING_FROM + d * t;')\n        p.append('}')\n        p.append('function rssiColor(r) {')\n        p.append('  if (r >= -50) return [80, 255, 80];')\n        p.append('  if (r >= -65) return [160, 255, 80];')\n        p.append('  if (r >= -80) return [255, 220, 60];')\n        p.append('  if (r >= -95) return [255, 140, 40];')\n        p.append('  return [255, 60, 60];')\n        p.append('}')\n        p.append('function drawGrid() {')\n        p.append('  ctx.clearRect(0, 0, W, H);')\n        p.append('  var bg = ctx.createRadialGradient(CX, CY, 10, CX, CY, RAD * 1.3);')\n        p.append('  bg.addColorStop(0, \"rgba(0, 40, 0, 0.9)\");')\n        p.append('  bg.addColorStop(1, \"rgba(0, 0, 0, 0.95)\");')\n        p.append('  ctx.fillStyle = bg; ctx.fillRect(0, 0, W, H);')\n        p.append('  var rings = [')\n        p.append('    {r: 1.0, label: \"30 \u043c\"},')\n        p.append('    {r: 0.66, label: \"10 \u043c\"},')\n        p.append('    {r: 0.33, label: \"3 \u043c\"},')\n        p.append('    {r: 0.11, label: \"0.5 \u043c\"}')\n        p.append('  ];')\n        p.append('  ctx.strokeStyle = \"rgba(0, 255, 0, 0.35)\";')\n        p.append('  ctx.lineWidth = 1;')\n        p.append('  for (var i = 0; i < rings.length; i++) {')\n        p.append('    ctx.beginPath();')\n        p.append('    ctx.arc(CX, CY, RAD * rings[i].r, 0, Math.PI * 2);')\n        p.append('    ctx.stroke();')\n        p.append('    ctx.fillStyle = \"rgba(0, 255, 0, 0.55)\";')\n        p.append('    ctx.font = \"10px monospace\";')\n        p.append('    ctx.fillText(rings[i].label, CX + 4,')\n        p.append('                 CY - RAD * rings[i].r + 12);')\n        p.append('  }')\n        p.append('  ctx.strokeStyle = \"rgba(0, 255, 0, 0.18)\";')\n        p.append('  for (var a = 0; a < 8; a++) {')\n        p.append('    var ang = a * Math.PI / 4;')\n        p.append('    ctx.beginPath();')\n        p.append('    ctx.moveTo(CX, CY);')\n        p.append('    ctx.lineTo(CX + Math.cos(ang) * RAD,')\n        p.append('               CY + Math.sin(ang) * RAD);')\n        p.append('    ctx.stroke();')\n        p.append('  }')\n        p.append('  ctx.fillStyle = \"#00ff00\";')\n        p.append('  ctx.beginPath();')\n        p.append('  ctx.arc(CX, CY, 4, 0, Math.PI * 2);')\n        p.append('  ctx.fill();')\n        p.append('}')\n        p.append('function drawDevices(headingDeg) {')\n        p.append('  var t = Date.now() / 500;')\n        p.append('  var headingRad = headingDeg * Math.PI / 180;')\n        p.append('  var pitch = IS_3D ? 0.58 : 0.0;')\n        p.append('  for (var i = 0; i < DEVICES.length; i++) {')\n        p.append('    var dev = DEVICES[i];')\n        p.append('    var d = dev.distance;')\n        p.append('    if (d < 0.3) d = 0.3;')\n        p.append('    var ratio = Math.min(1, d / 30);')\n        p.append('    var r = ratio * RAD;')\n        p.append('    var screenRad = dev.angle * Math.PI / 180 - headingRad;')\n        p.append('    var wx = Math.sin(screenRad) * r;')\n        p.append('    var wy = -Math.cos(screenRad) * r;')\n        p.append('    var cosP = Math.cos(pitch); var sinP = Math.sin(pitch);')\n        p.append('    var y1 = wy * cosP - (dev.elevation || 0) * sinP;')\n        p.append('    var z1 = wy * sinP + (dev.elevation || 0) * cosP;')\n        p.append('    var scale = IS_3D ? (460 / (460 + y1 * 0.7)) : 1;')\n        p.append('    var px = CX + wx * scale;')\n        p.append('    var py = (IS_3D ? (CY + 15) : CY) + z1 * scale;')\n        p.append('    var col = rssiColor(dev.rssi);')\n        p.append('    var pulse = 0.7 + 0.3 * Math.sin(t + i);')\n        p.append('    var size = (6 + 4 * pulse) * scale;')\n        p.append('    var halo = ctx.createRadialGradient(px, py, 0, px, py, size * 2.8);')\n        p.append('    halo.addColorStop(0, \"rgba(\" + col[0] + \",\" + col[1] + \",\" + col[2] + \",0.65)\");')\n        p.append('    halo.addColorStop(1, \"rgba(\" + col[0] + \",\" + col[1] + \",\" + col[2] + \",0)\");')\n        p.append('    ctx.fillStyle = halo;')\n        p.append('    ctx.beginPath(); ctx.arc(px, py, size * 2.8, 0, Math.PI * 2); ctx.fill();')\n        p.append('    ctx.fillStyle = \"rgb(\" + col[0] + \",\" + col[1] + \",\" + col[2] + \")\";')\n        p.append('    ctx.beginPath(); ctx.arc(px, py, Math.max(3, size * 0.5), 0, Math.PI * 2); ctx.fill();')\n        p.append('    ctx.fillStyle = \"rgba(255,255,255,0.92)\";')\n        p.append('    ctx.font = \"bold 10px monospace\";')\n        p.append('    var label = dev.name.length > 14 ? dev.name.substring(0, 14) + \"\u2026\" : dev.name;')\n        p.append('    ctx.fillText(label, px + size, py - size);')\n        p.append('    ctx.fillStyle = \"rgba(120, 255, 120, 0.75)\";')\n        p.append('    ctx.font = \"8px monospace\";')\n        p.append('    ctx.fillText(dev.distance.toFixed(1) + \"m (\" + (dev.confidence || 75) + \"% prec)\", px + size, py + 8);')\n        p.append('  }')\n        p.append('}')\n        p.append('function drawSweep() {')\n        # \u2500\u2500 \u0424\u0418\u041a\u0421: \u0444\u0430\u0437\u0430 \u043e\u0442 \u0430\u0431\u0441\u043e\u043b\u044e\u0442\u043d\u043e\u0433\u043e \u0432\u0440\u0435\u043c\u0435\u043d\u0438 \u044d\u043f\u043e\u0445\u0438, \u041d\u0415 \u043e\u0442 \u043c\u043e\u043c\u0435\u043d\u0442\u0430 \u043f\u0430\u0440\u0441\u0438\u043d\u0433\u0430 \u2500\u2500\n        p.append('  var elapsed = mono_ms() / 1000;')\n        p.append('  var sweepAngle = (elapsed * SWEEP_SPEED) % (Math.PI * 2);')\n        p.append('  var canvasAngle = sweepAngle - Math.PI / 2;')\n        p.append('  var grad = ctx.createRadialGradient(CX, CY, 0, CX, CY, RAD);')\n        p.append('  grad.addColorStop(0, \"rgba(0, 255, 0, 0.55)\");')\n        p.append('  grad.addColorStop(1, \"rgba(0, 255, 0, 0)\");')\n        p.append('  ctx.fillStyle = grad;')\n        p.append('  ctx.beginPath();')\n        p.append('  ctx.moveTo(CX, CY);')\n        p.append('  ctx.arc(CX, CY, RAD, canvasAngle - 0.55, canvasAngle);')\n        p.append('  ctx.closePath();')\n        p.append('  ctx.fill();')\n        p.append('  ctx.strokeStyle = \"rgba(140, 255, 140, 0.95)\";')\n        p.append('  ctx.lineWidth = 1.5;')\n        p.append('  ctx.beginPath();')\n        p.append('  ctx.moveTo(CX, CY);')\n        p.append('  ctx.lineTo(CX + Math.cos(canvasAngle) * RAD,')\n        p.append('             CY + Math.sin(canvasAngle) * RAD);')\n        p.append('  ctx.stroke();')\n        p.append('}')\n        p.append('function drawCompass(headingDeg) {')\n        p.append('  if (!COMPASS_ON) return;')\n        p.append('  var headingRad = headingDeg * Math.PI / 180;')\n        p.append('  var labels = [')\n        p.append('    {t: \"N\", a: 0, c: \"#ff6a6a\"},')\n        p.append('    {t: \"E\", a: 90, c: \"rgba(120,255,120,0.75)\"},')\n        p.append('    {t: \"S\", a: 180, c: \"rgba(120,255,120,0.75)\"},')\n        p.append('    {t: \"W\", a: 270, c: \"rgba(120,255,120,0.75)\"}')\n        p.append('  ];')\n        p.append('  ctx.textAlign = \"center\";')\n        p.append('  ctx.textBaseline = \"middle\";')\n        p.append('  for (var i = 0; i < labels.length; i++) {')\n        p.append('    var L = labels[i];')\n        p.append('    var angRad = L.a * Math.PI / 180 - headingRad;')\n        p.append('    var x = CX + Math.sin(angRad) * RLABEL;')\n        p.append('    var y = CY - Math.cos(angRad) * RLABEL;')\n        p.append('    ctx.font = \"bold 14px monospace\";')\n        p.append('    ctx.fillStyle = L.c;')\n        p.append('    ctx.fillText(L.t, x, y);')\n        p.append('  }')\n        p.append('  ctx.textAlign = \"start\";')\n        p.append('  ctx.textBaseline = \"alphabetic\";')\n        p.append('}')\n        p.append('function drawForward() {')\n        p.append('  var yb = CY - RAD - 6;')\n        p.append('  ctx.fillStyle = \"rgba(120, 255, 120, 0.9)\";')\n        p.append('  ctx.beginPath();')\n        p.append('  ctx.moveTo(CX - 7, yb - 9);')\n        p.append('  ctx.lineTo(CX + 7, yb - 9);')\n        p.append('  ctx.lineTo(CX, yb);')\n        p.append('  ctx.closePath();')\n        p.append('  ctx.fill();')\n        p.append('}')\n        p.append('function drawHeadingText(headingDeg) {')\n        p.append('  if (!COMPASS_ON) return;')\n        p.append('  ctx.fillStyle = \"rgba(120, 255, 120, 0.85)\";')\n        p.append('  ctx.font = \"bold 12px monospace\";')\n        p.append('  ctx.textAlign = \"center\";')\n        p.append('  ctx.fillText(Math.round(headingDeg) + \"\u00b0\", CX, CY + RAD + 22);')\n        p.append('  ctx.textAlign = \"start\";')\n        p.append('}')\n        p.append('function drawEmpty() {')\n        p.append('  if (DEVICES.length > 0) return;')\n        p.append('  ctx.fillStyle = \"rgba(0, 255, 0, 0.6)\";')\n        p.append('  ctx.font = \"13px monospace\";')\n        p.append('  ctx.textAlign = \"center\";')\n        p.append('  ctx.fillText(\"\u041e\u0416\u0418\u0414\u0410\u041d\u0418\u0415 \u0423\u0421\u0422\u0420\u041e\u0419\u0421\u0422\u0412\", CX, CY + RAD + 52);')\n        p.append('  ctx.font = \"11px monospace\";')\n        p.append('  ctx.fillStyle = \"rgba(0, 255, 0, 0.4)\";')\n        p.append('  ctx.fillText(\"\u0437\u0430\u043f\u0443\u0441\u0442\u0438\u0442\u0435 \u0441\u043a\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435\", CX, CY + RAD + 72);')\n        p.append('  ctx.textAlign = \"start\";')\n        p.append('}')\n        p.append('function loop() {')\n        p.append('  var h = currentHeading();')\n        p.append('  drawGrid();')\n        p.append('  drawDevices(h);')\n        p.append('  drawSweep();')\n        p.append('  drawCompass(h);')\n        p.append('  drawForward();')\n        p.append('  drawHeadingText(h);')\n        p.append('  drawEmpty();')\n        p.append('  requestAnimationFrame(loop);')\n        p.append('}')\n        p.append('window.addEventListener(\"resize\", resize);')\n        p.append('resize();')\n        p.append('loop();')\n        p.append('</script></body></html>')\n        return ''.join(p)\n\n    # \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 UI-\u0441\u0435\u043a\u0446\u0438\u0438 \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\n    def _button(self, ui, title, cb, *args, enabled=True, style=\"tonal\"):\n        return ui.button(title, self._bind(cb, *args),\n                         enabled=bool(enabled), style=style)\n\n    def _navigation(self, ui):\n        labels = [(\"radar\", \"\ud83d\udce1 \u0420\u0430\u0434\u0430\u0440\"),\n                  (\"list\", \"\ud83d\udccb \u0421\u043f\u0438\u0441\u043e\u043a\"),\n                  (\"logs\", \"\ud83d\udcdd \u041b\u043e\u0433\u0438\")]\n        buttons = []\n        for page, title in labels:\n            selected = self._page == page\n            buttons.append(ui.button(\n                title,\n                self._bind(self._go, page),\n                style=\"filled\" if selected else \"tonal\"))\n        return ui.row(buttons)\n\n    def _radar_ui(self, ui):\n        if self._scanning:\n            status_text = \"\ud83d\udfe2 \u0421\u043a\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 \u0430\u043a\u0442\u0438\u0432\u043d\u043e\"\n            status_color = \"success\"\n        else:\n            status_text = \"\u26aa \u0421\u043a\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043e\"\n            status_color = \"secondary\"\n\n        if self._compass_sensor_id is not None and self._heading_valid:\n            compass_line = \"\ud83e\udded {}\".format(int(round(self._heading_deg)))\n        elif self._compass_sensor_id is not None:\n            compass_line = \"\ud83e\udded \u043e\u0436\u0438\u0434\u0430\u043d\u0438\u0435 \u0434\u0430\u043d\u043d\u044b\u0445 \u0441\u0435\u043d\u0441\u043e\u0440\u0430\"\n        elif self._compass_failed:\n            compass_line = \"\ud83e\udded \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u0435\u043d \u043d\u0430 \u044d\u0442\u043e\u043c \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0435\"\n        else:\n            compass_line = \"\ud83e\udded \u0437\u0430\u043f\u0443\u0441\u043a\u2026\"\n\n        devices = self._get_devices_snapshot()\n        count = len(devices)\n\n        children = [\n            ui.card([\n                ui.text(\"\ud83d\udce1  BLE RADAR\", \"labelSmall\", color=\"secondary\"),\n                ui.text(status_text, \"titleMedium\", color=status_color),\n                ui.text(\"\u0423\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432: {}  \u00b7  \u0432\u0441\u0435\u0433\u043e: {}  \u00b7  \u043f\u0430\u043a\u0435\u0442\u043e\u0432: {}\".format(\n                    count, self._unique_total, self._batches_received),\n                    \"bodyMedium\"),\n                ui.text(compass_line, \"bodySmall\", color=\"muted\"),\n                ui.row([\n                    self._button(ui, \"\u25b6\ufe0f  \u0421\u0442\u0430\u0440\u0442\", self._start_scan,\n                                 enabled=not self._scanning, style=\"filled\"),\n                    self._button(ui, \"\u23f9  \u0421\u0442\u043e\u043f\", self._stop_scan,\n                                 enabled=self._scanning),\n                ]),\n                ui.switch(\n                    checked=bool(self._compass_enabled),\n                    on_change=self._bind_evt(self._set_compass_enabled),\n                    title=\"\u041a\u043e\u043c\u043f\u0430\u0441\",\n                    subtitle=\"\u041f\u043e\u0432\u043e\u0440\u043e\u0442 \u0442\u043e\u0447\u0435\u043a \u043f\u043e \u043e\u0440\u0438\u0435\u043d\u0442\u0430\u0446\u0438\u0438 \u0442\u0435\u043b\u0435\u0444\u043e\u043d\u0430\",\n                ),\n                ui.switch(\n                    checked=bool(getattr(self, \"_mode_3d\", True)),\n                    on_change=self._bind_evt(lambda val: setattr(self, \"_mode_3d\", bool(val))),\n                    title=\"3D \u041f\u0435\u0440\u0441\u043f\u0435\u043a\u0442\u0438\u0432\u0430\",\n                    subtitle=\"\u0418\u0437\u043e\u043c\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u043f\u0440\u043e\u0435\u043a\u0446\u0438\u044f \u0441 \u0432\u044b\u0441\u043e\u0442\u043e\u0439\",\n                ),\n                ui.switch(\n                    checked=bool(getattr(self, \"_wifi_csi_enabled\", True)),\n                    on_change=self._bind_evt(lambda val: setattr(self, \"_wifi_csi_enabled\", bool(val))),\n                    title=\"Wi-Fi 7 CSI Link\",\n                    subtitle=\"\u041a\u043e\u043c\u043f\u0435\u043d\u0441\u0430\u0446\u0438\u044f \u0441\u043a\u0432\u043e\u0437\u044c \u0441\u0442\u0435\u043d\u044b \u0438 \u0441\u0443\u0431\u043c\u0435\u0442\u0440\u043e\u0432\u0430\u044f \u0442\u043e\u0447\u043d\u043e\u0441\u0442\u044c\",\n                ),\n            ]),\n        ]\n\n        try:\n            html = self._build_radar_html()\n            children.append(ui.card([\n                ui.webview(html=html, height=self.WEBVIEW_HEIGHT,\n                           fill_max_size=False),\n            ], padding=4))\n        except Exception as e:\n            self._log(\"error\", \"webview: \" + str(e)[:200])\n            children.append(ui.card([\n                ui.text(\"WebView \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u0435\u043d\", \"bodyMedium\", color=\"error\"),\n                ui.text(str(e)[:200], \"bodySmall\", color=\"muted\"),\n            ]))\n\n        return children\n\n    def _sort_chips(self, ui):\n        chips = []\n        options = [(self.SORT_RSSI, \"RSSI\"),\n                   (self.SORT_RECENT, \"\u0421\u0432\u0435\u0436\u0438\u0435\"),\n                   (self.SORT_NAME, \"\u0418\u043c\u044f\"),\n                   (self.SORT_SEEN, \"\u0427\u0430\u0441\u0442\u043e\u0442\u0430\")]\n        for value, label in options:\n            chips.append(ui.chip(\n                label,\n                selected=(self._sort_mode == value),\n                on_click=self._bind(self._set_sort, value)))\n        return ui.row(chips)\n\n    def _min_rssi_chips(self, ui):\n        values = (-100, -90, -80, -70, -60)\n        row1 = []\n        row2 = []\n        for i, value in enumerate(values):\n            chip = ui.chip(\n                \"{} dBm\".format(value),\n                selected=(int(self._min_rssi) == value),\n                on_click=self._bind(self._set_min_rssi, value))\n            if i < 3:\n                row1.append(chip)\n            else:\n                row2.append(chip)\n        return ui.column([ui.row(row1), ui.row(row2)], spacing=4)\n\n    def _list_ui(self, ui):\n        devices = self._sorted_devices()\n\n        children = [ui.card([\n            ui.text(\"\ud83d\udccb  \u0423\u0421\u0422\u0420\u041e\u0419\u0421\u0422\u0412\u0410\", \"labelSmall\", color=\"secondary\"),\n            ui.text(\"\u041f\u043e\u043a\u0430\u0437\u0430\u043d\u043e: {} \u0438\u0437 {}\".format(\n                len(devices), len(self._get_devices_snapshot())),\n                \"titleMedium\"),\n            ui.text(\"\u0421\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u043a\u0430\", \"labelSmall\", color=\"secondary\"),\n            self._sort_chips(ui),\n            ui.text(\"\u041c\u0438\u043d. RSSI\", \"labelSmall\", color=\"secondary\"),\n            self._min_rssi_chips(ui),\n            ui.row([\n                self._button(ui, \"\ud83d\udcc4  CSV\", self._export_csv, style=\"filled\"),\n                self._button(ui, \"\ud83d\uddd1  \u041e\u0447\u0438\u0441\u0442\u0438\u0442\u044c\", self._clear_devices),\n            ]),\n        ])]\n\n        if not devices:\n            children.append(ui.card([\n                ui.text(\"\u041f\u043e\u043a\u0430 \u043f\u0443\u0441\u0442\u043e\", \"bodyMedium\", color=\"secondary\"),\n                ui.text(\"\u0417\u0430\u043f\u0443\u0441\u0442\u0438 \u0441\u043a\u0430\u043d \u043d\u0430 \u0432\u043a\u043b\u0430\u0434\u043a\u0435 \u00ab\u0420\u0430\u0434\u0430\u0440\u00bb \u0438\u043b\u0438 \u0441\u043d\u0438\u0437\u044c \u043c\u0438\u043d. RSSI\",\n                        \"bodySmall\", color=\"muted\"),\n            ]))\n            return children\n\n        now = time.time()\n        for i, d in enumerate(devices):\n            rssi_show = d.get(\"rssi_smooth\", d.get(\"rssi\", -100))\n            dist = self._rssi_to_distance(rssi_show, self.TX_POWER, self.N_FACTOR)\n            dist_str = self._distance_text(dist)\n            col = self._level_color(int(round(rssi_show)))\n            name = d.get(\"name\") or \"\u0411\u0435\u0437 \u0438\u043c\u0435\u043d\u0438\"\n            vendor = d.get(\"vendor\") or \"Generic\"\n            uuid_str = d.get(\"uuid\") or \"0000FD6F-0000-1000-8000-00805F9B34FB\"\n            uid_str = d.get(\"uid\") or \"DOLPHY-NODE\"\n            conf = int(d.get(\"confidence\", 75))\n            ago = int(now - d.get(\"last_seen\", now))\n            children.append(ui.card([\n                ui.text(\"{}. {} [{}]\".format(i + 1, name, vendor), \"titleMedium\"),\n                ui.text(\"MAC: {}\".format(d.get(\"address\", \"\")), \"bodySmall\", color=\"muted\"),\n                ui.text(\"UUID: {}\".format(uuid_str), \"bodySmall\", color=\"secondary\"),\n                ui.text(\"UID: {}\".format(uid_str), \"bodySmall\", color=\"muted\"),\n                ui.text(\"RSSI: {:.0f} dBm  \u00b7  ~{}  \u00b7  \u0422\u043e\u0447\u043d\u043e\u0441\u0442\u044c: {}%\".format(rssi_show, dist_str, conf),\n                        \"bodyMedium\", color=col),\n                ui.text(\"\u0432\u0438\u0434\u0435\u043d {} \u0440\u0430\u0437  \u00b7  {} \u0441\u0435\u043a \u043d\u0430\u0437\u0430\u0434\".format(\n                    d.get(\"seen\", 0), ago), \"bodySmall\", color=\"muted\"),\n            ]))\n\n        return children\n\n    def _logs_ui(self, ui):\n        with self._log_lock:\n            total = len(self._logs)\n            items = list(self._logs[-self.LOG_UI_LINES:])\n\n        children = [ui.card([\n            ui.text(\"\ud83d\udcdd  \u041b\u041e\u0413\u0418\", \"labelSmall\", color=\"secondary\"),\n            ui.text(\"\u0417\u0430\u043f\u0438\u0441\u0435\u0439: {}\".format(total), \"titleMedium\"),\n            ui.row([\n                self._button(ui, \"\ud83d\udcbe  \u042d\u043a\u0441\u043f\u043e\u0440\u0442\", self._export_logs, style=\"filled\"),\n                self._button(ui, \"\ud83d\udcc4  \u041a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c\", self._copy_logs),\n            ]),\n            self._button(ui, \"\ud83d\uddd1  \u041e\u0447\u0438\u0441\u0442\u0438\u0442\u044c \u043b\u043e\u0433\u0438\", self._clear_logs, style=\"text\"),\n            ui.text(\"\u0424\u0430\u0439\u043b: {}/{}\".format(self.EXPORT_DIR, self.FILE_LOG),\n                    \"bodySmall\", color=\"muted\"),\n        ])]\n\n        if total == 0:\n            children.append(ui.card([\n                ui.text(\"\u041b\u043e\u0433\u0438 \u043f\u0443\u0441\u0442\u044b\", \"bodyMedium\", color=\"secondary\"),\n                ui.text(\"\u0417\u0430\u043f\u0443\u0441\u0442\u0438 \u0441\u043a\u0430\u043d \u043d\u0430 \u0432\u043a\u043b\u0430\u0434\u043a\u0435 \u00ab\u0420\u0430\u0434\u0430\u0440\u00bb\",\n                        \"bodySmall\", color=\"muted\"),\n            ]))\n            return children\n\n        colors = {\"error\": \"error\", \"warning\": \"warning\",\n                  \"success\": \"success\", \"info\": \"secondary\"}\n        marks = {\"error\": \"\u2716\", \"warning\": \"\u26a0\",\n                 \"success\": \"\u2714\", \"info\": \"\u2022\"}\n        lines = []\n        for lvl, stamp, msg in reversed(items):\n            lines.append(ui.text(\n                \"{} {}  {}\".format(marks.get(lvl, \"\u2022\"), stamp, msg),\n                \"labelSmall\", color=colors.get(lvl, \"secondary\")))\n        children.append(ui.card(lines))\n        return children\n\n    # \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 \u0422\u043e\u0447\u043a\u0430 \u0432\u0445\u043e\u0434\u0430 \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\n    def screen_main(self, ui, api, state):\n        try:\n            self.api = api\n\n            if not self._ready:\n                return ui.scaffold(\n                    title=\"BLE Radar Locator\",\n                    content=ui.column([\n                        ui.text(\"\u041f\u043b\u0430\u0433\u0438\u043d \u043d\u0435 \u0433\u043e\u0442\u043e\u0432\",\n                                \"titleMedium\", color=\"warning\"),\n                        ui.text(self._init_error or \"\u043d\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u043d\u0430\u044f \u043f\u0440\u0438\u0447\u0438\u043d\u0430\",\n                                \"bodySmall\", color=\"muted\"),\n                    ], padding=16, spacing=8, fill_max_size=False))\n\n            if (self._compass_sensor_id is None\n                    and not self._compass_failed\n                    and self._compass_attempts < self.COMPASS_MAX_ATTEMPTS):\n                try:\n                    self._start_compass()\n                except Exception:\n                    pass\n\n            nav = self._navigation(ui)\n\n            if self._page == \"radar\":\n                body = self._radar_ui(ui)\n                content = ui.column([nav] + body, padding=12, spacing=8,\n                                    fill_max_size=False)\n            elif self._page == \"list\":\n                body = self._list_ui(ui)\n                content = ui.lazy_column([nav] + body, padding=12, spacing=8,\n                                         fill_max_size=True)\n            else:\n                body = self._logs_ui(ui)\n                content = ui.lazy_column([nav] + body, padding=12, spacing=8,\n                                         fill_max_size=True)\n\n            return ui.scaffold(title=\"BLE Radar Locator\", content=content)\n\n        except Exception as exc:\n            try:\n                self._log(\"error\", \"UI: \" + str(exc)[:240])\n            except Exception:\n                pass\n            try:\n                return ui.scaffold(\n                    title=\"BLE Radar Locator\",\n                    content=ui.column([\n                        ui.text(\"\u041e\u0448\u0438\u0431\u043a\u0430 UI\", \"titleLarge\", color=\"error\"),\n                        ui.text(str(exc)[:300], \"bodySmall\", color=\"warning\"),\n                        ui.button(\"\u041d\u0430 \u0440\u0430\u0434\u0430\u0440\",\n                                  self._bind(self._go, \"radar\"),\n                                  style=\"tonal\"),\n                    ], padding=16, spacing=10, fill_max_size=False))\n            except Exception:\n                return ui.scaffold(title=\"\u041e\u0448\u0438\u0431\u043a\u0430\",\n                                   content=ui.text(\"UI \u0441\u043b\u043e\u043c\u0430\u043d\"))";
}
